if (points.size() <= 1) return points;

std::vector<Point2d> sorted = points;
std::sort(sorted.begin(), sorted.end(), [](const Point2d& a, const Point2d& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
});

std::vector<Point2d> hull;
hull.reserve(sorted.size());

// Lower hull
for (const auto& p : sorted) {
    while (hull.size() >= 2) {
        const Point2d& a = hull[hull.size() - 2];
        const Point2d& b = hull.back();
        double cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
        if (cross <= 0) hull.pop_back();
        else break;
    }
    hull.push_back(p);
}

// Upper hull
size_t lower_size = hull.size();
for (int i = static_cast<int>(sorted.size()) - 2; i >= 0; --i) {
    const Point2d& p = sorted[i];
    while (hull.size() > lower_size) {
        const Point2d& a = hull[hull.size() - 2];
        const Point2d& b = hull.back();
        double cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
        if (cross <= 0) hull.pop_back();
        else break;
    }
    hull.push_back(p);
}

if (hull.size() > 1) hull.pop_back(); // Remove duplicate first point

return hull;

